// Utility functions
function getAllBlogs() {
    return BLOG_POSTS;
}

function getBlogById(id) {
    return BLOG_POSTS.find(blog => blog.id === id);
}

function getRecentBlogs(count = 3) {
    return [...BLOG_POSTS].slice(0, count);
}
